        var value = event.target.value;
        KEY = event.target.value;
        this.setState({
            value
        });
      }

      NewKEY = KEY => {
        axios
        .get(`${URL}key=${KEY}`)
        .then(({ data }) => {           
          const { departures } = data;
          const liste = [departures[0], departures[1], departures[2], departures[3], departures[4],departures[5]];
          this.setState({ liste });
        })
        .catch(console.error);
       };

